body.script:
const owner = 'lotsacookie;
const repo = 'kstuff;
const filePath = 'Pages/gfn/assets/main.js';

fetch(`https://api.github.com/repos/${owner}/${repo}/commits?path=${filePath}&per_page=1`)
    .then(res => res.json())
    .then(data => {
        if (data && data[0] && data[0].sha) {
            const sha = data[0].sha;
            const scriptUrl = `https://cdn.jsdelivr.net/gh/${owner}/${repo}@${sha}/${filePath}`;
            const script = document.createElement('script');
            script.src = scriptUrl;
            document.body.appendChild(script);
        }
    })
    .catch(err => console.error(err));
